+		key, err := jsonutil.MarshalWithNoHTMLEscape(k)
+		if err != nil {
+			return nil, err //nolint:wrapcheck // returned from MarshalJSON; encoding/json adds context
+		}
+		if needComma {
+			buf.WriteByte(',')
+		}
+		needComma = true
